window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-36901\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυθρωπασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 751 na letra σ · nº geral 36901</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ar sombrio; semblante contrariado. 〈σκυθρωπάζω〉</p></section></article>\n<article id=\"entry-dgp-36902\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυθρωπός, ός</h1><div class=\"entry-meta\"><span>DGP · ordem 752 na letra σ · nº geral 36902</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ή, όν 1 contrariado; zangado; carrancudo 2 nefasto (dia) 3 grave; severo ♦ τὸ σκυθρωπόν 4 ar aborrecido; mau humor. 〈σκυθρός, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-36903\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυθρωπῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 753 na letra σ · nº geral 36903</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com mau humor; com ar carrancudo.</p></section></article>\n<article id=\"entry-dgp-36904\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλακεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 754 na letra σ · nº geral 36904</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criação de cães. 〈σκυλακεύω〉</p></section></article>\n<article id=\"entry-dgp-36905\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλακεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 755 na letra σ · nº geral 36905</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 acasalar cães 2 criar cães 3 aleitar cães.</p></section></article>\n<article id=\"entry-dgp-36906\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλάκιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 756 na letra σ · nº geral 36906</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filhote de cachorro. 〈σκύλαξ〉</p></section></article>\n<article id=\"entry-dgp-36907\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλακοτροφικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 757 na letra σ · nº geral 36907</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de criação de filhotes de cães. 〈σκύλαξ, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-36908\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλακώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 758 na letra σ · nº geral 36908</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de filhote de cão ♦ τὸ σκυλακῶδες 2 temperamento carinhoso de filhote de cão. 〈σκύλαξ, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-36909\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύλαξ, ακος (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 759 na letra σ · nº geral 36909</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 filhote de cão 2 cão 3 filhote 4 colar ou coleira.</p></section></article>\n<article id=\"entry-dgp-36910\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύλευμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 760 na letra σ · nº geral 36910</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">despojo. 〈σκυλέυω〉</p></section></article>\n<article id=\"entry-dgp-36911\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 761 na letra σ · nº geral 36911</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 espoliar, despojar um inimigo morto, ac., de algo, ac. ou gen. ou ἀπό e gen. 2 despojar 3 pilhar (cidade). 〈σκῦλον〉</p></section></article>\n<article id=\"entry-dgp-36912\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκύλλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 762 na letra σ · nº geral 36912</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Cila, monstro marinho.</p></section></article>\n<article id=\"entry-dgp-36913\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκύλλα</h1><div class=\"entry-meta\"><span>DGP · ordem 763 na letra σ · nº geral 36913</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ép. = Σκύλλη.</p></section></article>\n<article id=\"entry-dgp-36914\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύλλω</h1><div class=\"entry-meta\"><span>DGP · ordem 764 na letra σ · nº geral 36914</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. desus.; aor. ἔσκυλα; pas. aor. ἐσκύλθην, aor.2 ἐσκύλην, perf. ἔσκυλμαι) 1 esfolar; dilacerar 2 perturbar; molestar; incomodar ♦ 3 rapar a cabeça 4 bíbl. incomodar-se; fatigar-se.</p></section></article>\n<article id=\"entry-dgp-36915\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλοδεψέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 765 na letra σ · nº geral 36915</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ser curtidor de peles. 〈σκυλοδέψης〉</p></section></article>\n<article id=\"entry-dgp-36916\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυλοδέψης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 766 na letra σ · nº geral 36916</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">curtidor de peles. 〈σκύλος, δέψω〉</p></section></article>\n<article id=\"entry-dgp-36917\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκῦλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 767 na letra σ · nº geral 36917</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saque; pilhagem; espólio 2 ger. pl. armas pilhadas de um inimigo morto; despojos.</p></section></article>\n<article id=\"entry-dgp-36918\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύλος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 768 na letra σ · nº geral 36918</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele (de animal) 2 invólucro; casca (de noz).</p></section></article>\n<article id=\"entry-dgp-36919\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύμνος, ου (ὁ, ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 769 na letra σ · nº geral 36919</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 filhote; cria de animal 2 criança; filho.</p></section></article>\n<article id=\"entry-dgp-36920\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύνιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 770 na letra σ · nº geral 36920</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sobrancelha.</p></section></article>\n<article id=\"entry-dgp-36921\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύριος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 771 na letra σ · nº geral 36921</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Ciros ♦ οἱ Σκύριοι 2 habitantes de Ciros. 〈Σκῦρος〉</p></section></article>\n<article id=\"entry-dgp-36922\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυρόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 772 na letra σ · nº geral 36922</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. vindo de Ciros. 〈Σκῦρος, -θεν〉</p></section></article>\n<article id=\"entry-dgp-36923\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκῦρος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 773 na letra σ · nº geral 36923</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Ciros, n. de uma ilha das Espórades e de uma cidade da Frígia.</p></section></article>\n<article id=\"entry-dgp-36924\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτάλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 774 na letra σ · nº geral 36924</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ramo; broto 2 bastão 3 bastão de extremidade grossa; clava; maça 4 bíbl. haste 5 rolo; cilindro 6 cítale, em Esparta, bastão de madeira no qual se enrolavam os comunicados que os éforos enviavam aos generais espartanos 7 despacho; mensagem oficial 8 etiqueta; rótulo 9 mensageiro; núncio 10 espécie de peixe 11 espécie de serpente 12 lâmina de metal 13 alavanca; manivela de máquina.</p></section></article>\n<article id=\"entry-dgp-36925\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυταλίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 775 na letra σ · nº geral 36925</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bastão pequeno; vareta 2 pequeno cilindro de madeira 3 pequena cítale (cf. σκυτάλη) 4 espécie de suporte usado pelo pescador para enrolar a rede e fixa-lá na terra 5 sarmento 6 falange dos dedos. 〈σκυτάλη〉</p></section></article>\n<article id=\"entry-dgp-36926\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυταλισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 776 na letra σ · nº geral 36926</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a Bastonada, sublevação em Argos, assim nomeada por causa do suplício infligido sobre os culpados. 〈σκυτάλη〉</p></section></article>\n<article id=\"entry-dgp-36927\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύταλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 777 na letra σ · nº geral 36927</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">clava; maça; porrete. 〈σκυτάλη〉</p></section></article>\n<article id=\"entry-dgp-36928\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 778 na letra σ · nº geral 36928</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 artesão que trabalha com couro 2 sapateiro. 〈σκῦτος〉</p></section></article>\n<article id=\"entry-dgp-36929\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 779 na letra σ · nº geral 36929</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trabalhar com o couro 2 ser sapateiro. 〈σκῦτος〉</p></section></article>\n<article id=\"entry-dgp-36930\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 780 na letra σ · nº geral 36930</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de sapateiro 2 hábil em fazer sapatos ♦ ὁ σκυτικός 3 sapateiro ♦ ἡ σκυτική 4 arte do sapateiro. 〈σκῦτος〉</p></section></article>\n<article id=\"entry-dgp-36931\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύτινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 781 na letra σ · nº geral 36931</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de couro 2 feito de couro 3 pele e osso; esquálido (pessoa). 〈σκῦτος〉</p></section></article>\n<article id=\"entry-dgp-36932\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοδέψης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 782 na letra σ · nº geral 36932</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">curtidor de peles. 〈σκῦτος, δέψω〉</p></section></article>\n<article id=\"entry-dgp-36933\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοδεψός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 783 na letra σ · nº geral 36933</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σκυτοδέψης.</p></section></article>\n<article id=\"entry-dgp-36934\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκῦτος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 784 na letra σ · nº geral 36934</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele curtida de animal; couro 2 correia de couro; chicote: σκύτη βλέπειν ar. ter o chicote diante dos olhos, i.e., ter o ar de um cão surrado.</p></section></article>\n<article id=\"entry-dgp-36935\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοτομεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 785 na letra σ · nº geral 36935</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">loja de sapateiro; sapataria.</p></section></article>\n<article id=\"entry-dgp-36936\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοτομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 786 na letra σ · nº geral 36936</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ser sapateiro 2 confeccionar calçados com couro. 〈σκυτοτόμος〉</p></section></article>\n<article id=\"entry-dgp-36937\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοτομία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 787 na letra σ · nº geral 36937</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">profissão de sapateiro. 〈σκυτοτόμος〉</p></section></article>\n<article id=\"entry-dgp-36938\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοτομικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 788 na letra σ · nº geral 36938</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de ou para sapateiro ♦ ὁ σκυτοτομικός 2 sapateiro ♦ ἡ σκυτοτομική 3 arte do sapateiro. 〈σκυτοτόμος〉</p></section></article>\n<article id=\"entry-dgp-36939\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοτόμος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 789 na letra σ · nº geral 36939</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 que trabalha o couro ♦ ὁ σκυτοτόμος 2 artesão do couro 3 sapateiro. 〈σκῦτος, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-36940\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυτοτραγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 790 na letra σ · nº geral 36940</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">roer o couro. 〈σκῦτος, τρώγω〉</p></section></article>\n<article id=\"entry-dgp-36941\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 791 na letra σ · nº geral 36941</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">copo.</p></section></article>\n<article id=\"entry-dgp-36942\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκωληκόβρωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 792 na letra σ · nº geral 36942</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comido por vermes. 〈σκώληξ, βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-36943\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκώληξ, ηκος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 793 na letra σ · nº geral 36943</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 verme 2 larva de inseto 3 lombriga.</p></section></article>\n<article id=\"entry-dgp-36944\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκῶλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 794 na letra σ · nº geral 36944</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estaca; poste 2 espinho; ponta que pica.</p></section></article>\n<article id=\"entry-dgp-36945\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκῶμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 795 na letra σ · nº geral 36945</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">zombaria; sarcasmo. 〈σκώπτω〉</p></section></article>\n<article id=\"entry-dgp-36946\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκωπτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 796 na letra σ · nº geral 36946</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">zombeteiro; escarnecedor. 〈σκώπτω〉</p></section></article>\n<article id=\"entry-dgp-36947\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκώπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 797 na letra σ · nº geral 36947</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔσκωπτον, fut. σκώψω e σκώψομαι, aor. ἔσκωψα, perf. desus.; pas. aor. ἐσκώφθην, perf. ἔσκωμμαι) at. e méd. 1 zombar; escarnecer; caçoar de alguém ou de algo, ac., por algo, gen. ou εἰς e ac. 2 gracejar; divertir-se.</p></section></article>\n<article id=\"entry-dgp-36948\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκώρ, σκατός (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 798 na letra σ · nº geral 36948</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">excremento; fezes.</p></section></article>\n<article id=\"entry-dgp-36949\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκωραμίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 799 na letra σ · nº geral 36949</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">urinol. 〈σκώρ, ἀμίς〉</p></section></article>\n<article id=\"entry-dgp-36950\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκώψ, σκωπός (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 800 na letra σ · nº geral 36950</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tipo de coruja ou de mocho, lit. “ave que vigia” 2 dança cômica que imita os movimentos da coruja.</p></section></article>\n<article id=\"entry-dgp-36951\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμαράγδινος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 801 na letra σ · nº geral 36951</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de esmeralda; esmeraldino.</p></section></article>\n<article id=\"entry-dgp-36952\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμάραγδος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 802 na letra σ · nº geral 36952</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">esmeralda, pedra verde.</p></section></article>\n<article id=\"entry-dgp-36953\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμαραγέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 803 na letra σ · nº geral 36953</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 retumbar fortemente; ribombar 2 (intestino) roncar 3 fazer ressoar; fazer retinir.</p></section></article>\n<article id=\"entry-dgp-36954\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 804 na letra σ · nº geral 36954</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., com formas át. contr. em η, e aor. ἔσμησα) 1 esfregar; besuntar; untar ♦ méd. 2 esfregar-se; limpar-se ou lavar-se 3 esfregar para si ou em si: σμησάμενοι τὰς κεφαλάς her. após lavarem a cabeça.</p></section></article>\n<article id=\"entry-dgp-36955\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμερδαλέος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 805 na letra σ · nº geral 36955</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 terrível; assustador de ver ou de ouvir ♦ σμερδαλέον e σμερδαλέα adv. 2 de modo assustador.</p></section></article>\n<article id=\"entry-dgp-36956\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σμέρδις, ιος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 806 na letra σ · nº geral 36956</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Esmérdis, n. de h.</p></section></article>\n<article id=\"entry-dgp-36957\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμερδνός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 807 na letra σ · nº geral 36957</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σμερδαλέος.</p></section></article>\n<article id=\"entry-dgp-36958\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμῆγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 808 na letra σ · nº geral 36958</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">loção ou bálsamo de limpeza. 〈σμήχω〉</p></section></article>\n<article id=\"entry-dgp-36959\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμῆν</h1><div class=\"entry-meta\"><span>DGP · ordem 809 na letra σ · nº geral 36959</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. σμάω.</p></section></article>\n<article id=\"entry-dgp-36960\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμῆνον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 810 na letra σ · nº geral 36960</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">σμῆνος.</p></section></article>\n<article id=\"entry-dgp-36961\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμῆνος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 811 na letra σ · nº geral 36961</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 colméia 2 enxame de abelhas ou de vespas 3 enxame de pessoas ou de coisas.</p></section></article>\n<article id=\"entry-dgp-36962\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμηνουργός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 812 na letra σ · nº geral 36962</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criador de abelhas; apicultor. 〈σμῆνος, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-36963\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμήχω</h1><div class=\"entry-meta\"><span>DGP · ordem 813 na letra σ · nº geral 36963</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. impf. e aor. ἔσμηξα; pas. só perf. ἔσμηγμαι) 1 retirar esfregando 2 limpar esfregando ♦ méd. 3 limpar esfregando 4 esfregar-se; lavar-se.</p></section></article>\n<article id=\"entry-dgp-36964\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμικρογραφέω, σμικρολογέω, σμικρολογία</h1><div class=\"entry-meta\"><span>DGP · ordem 814 na letra σ · nº geral 36964</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = μικρογραφέω, μικρολογέω, μικρολογία.</p></section></article>\n<article id=\"entry-dgp-36965\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σμῖκρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 815 na letra σ · nº geral 36965</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Esmicro, n. de h.</p></section></article>\n<article id=\"entry-dgp-36966\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμικρύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 816 na letra σ · nº geral 36966</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = μικρύνω.</p></section></article>\n<article id=\"entry-dgp-36967\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμικρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 817 na letra σ · nº geral 36967</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = μικρῶς.</p></section></article>\n<article id=\"entry-dgp-36968\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμίλαξ, ακος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 818 na letra σ · nº geral 36968</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 teixo, arbusto 2 choupo-branco, árvore 3 norça, espécie de trepadeira. 〈σμίλη〉</p></section></article>\n<article id=\"entry-dgp-36969\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμίλη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 819 na letra σ · nº geral 36969</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 instrumento para cortar ou entalhar 2 cinzel 3 Medic. bisturi ou lanceta de cirurgião 4 faca de sapateiro ou de vinhateiro 5 estilete para escrever. (cf. σμάω)</p></section></article>\n<article id=\"entry-dgp-36970\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμιλίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 820 na letra σ · nº geral 36970</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de σμίλη.</p></section></article>\n<article id=\"entry-dgp-36971\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμινύη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 821 na letra σ · nº geral 36971</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tipo de enxada ou alvião de duas pontas.</p></section></article>\n<article id=\"entry-dgp-36972\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμυγερός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 822 na letra σ · nº geral 36972</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">miserável.</p></section></article>\n<article id=\"entry-dgp-36973\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμυγερῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 823 na letra σ · nº geral 36973</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. miseravelmente.</p></section></article>\n<article id=\"entry-dgp-36974\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμύρνα,</h1><div class=\"entry-meta\"><span>DGP · ordem 824 na letra σ · nº geral 36974</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. e eól. μύρρα, ης (ἡ) 1 mirra, goma de mirto da Arábia ♦ Σμύρνα 2 Esmirna, cidade da Jônia.</p></section></article>\n<article id=\"entry-dgp-36975\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σμυρναϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 825 na letra σ · nº geral 36975</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Σμυρναῖος.</p></section></article>\n<article id=\"entry-dgp-36976\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμυρναῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 826 na letra σ · nº geral 36976</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de mirra 2 de mirto. 〈σμύρνα〉</p></section></article>\n<article id=\"entry-dgp-36977\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σμυρναῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 827 na letra σ · nº geral 36977</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de Esmirna ♦ οἱ Σμυρναῖοι 2 os habitantes de Esmirna. 〈Σμύρνα〉</p></section></article>\n<article id=\"entry-dgp-36978\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σμύρνη</h1><div class=\"entry-meta\"><span>DGP · ordem 828 na letra σ · nº geral 36978</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Σμύρνα.</p></section></article>\n<article id=\"entry-dgp-36979\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμυρνίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 829 na letra σ · nº geral 36979</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bíbl. preparar ou misturar com mirra 2 ser parecido com a mirra.</p></section></article>\n<article id=\"entry-dgp-36980\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμύχω</h1><div class=\"entry-meta\"><span>DGP · ordem 830 na letra σ · nº geral 36980</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἔσμυξα) 1 queimar ou consumir em fogo brando 2 consumir; mirrar; corroer (alguém, coração) ♦ pas. 3 consumir-se ardendo; arder.</p></section></article>\n<article id=\"entry-dgp-36981\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σμῶδιξ, ιγγος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 831 na letra σ · nº geral 36981</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lesão proveniente de contusão; contusão.</p></section></article>\n<article id=\"entry-dgp-36982\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σοβαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 832 na letra σ · nº geral 36982</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 impetuoso; rápido; violento 2 que avança com passo rápido e altivo; que pavoneia (cavalo) 3 soberbo; altivo; arrogante 4 imponente; impressionante; grandioso 5 alto; elevado (preço) ♦ σοβαρόν adv. 6 com petulância.</p></section></article>\n<article id=\"entry-dgp-36983\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σοβαρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 833 na letra σ · nº geral 36983</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com impetuosidade 2 de maneira orgulhosa; com magnificência.</p></section></article>\n<article id=\"entry-dgp-36984\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σοβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 834 na letra σ · nº geral 36984</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. σοβήσω, aor, ἐσόβησα, perf. σεσόβηκα) 1 impelir vigorosamente; expulsar; afugentar 2 sacudir (poeira) 3 mover vigorosamente: σ. πόδα ἐν κύκλῳ ar. mover o pé em círculo, i.e., avançar dançando em círculo 4 fazer circular (a taça) 5 intr. avançar em passo rápido e altivo; avançar orgulhosamente; pavonear-se ♦ pas. 6 ser agitado: σεσοβημένος πρὸς δόξαν plut. agitado por um desejo de glória.</p></section></article>\n<article id=\"entry-dgp-36985\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σόβησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 835 na letra σ · nº geral 36985</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 passo precipitado; pressa 2 diligência. 〈σοβέω〉</p></section></article>\n<article id=\"entry-dgp-36986\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σογδιανή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 836 na letra σ · nº geral 36986</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Sogdiane, região da Ásia entre Jacarta e Oxus.</p></section></article>\n<article id=\"entry-dgp-36987\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σογδιανοί, ῶν (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 837 na letra σ · nº geral 36987</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Σόγδοι.</p></section></article>\n<article id=\"entry-dgp-36988\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σόγδοι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 838 na letra σ · nº geral 36988</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitantes de Sogdiane.</p></section></article>\n<article id=\"entry-dgp-36989\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σόδομα, ων (τά)</h1><div class=\"entry-meta\"><span>DGP · ordem 839 na letra σ · nº geral 36989</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Sodoma, cidade asiática.</p></section></article>\n<article id=\"entry-dgp-36990\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σόῃ, σόῃς</h1><div class=\"entry-meta\"><span>DGP · ordem 840 na letra σ · nº geral 36990</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. σόω.</p></section></article>\n<article id=\"entry-dgp-36991\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σοί</h1><div class=\"entry-meta\"><span>DGP · ordem 841 na letra σ · nº geral 36991</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. de σύ.</p></section></article>\n<article id=\"entry-dgp-36992\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σοῖο</h1><div class=\"entry-meta\"><span>DGP · ordem 842 na letra σ · nº geral 36992</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ép. de σός.</p></section></article>\n<article id=\"entry-dgp-36993\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σόλοι, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 843 na letra σ · nº geral 36993</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Solos, n. de cidade de Chipre e da Cilícia.</p></section></article>\n<article id=\"entry-dgp-36994\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σολοικία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 844 na letra σ · nº geral 36994</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">incorreção; falta. 〈σόλοικος〉</p></section></article>\n<article id=\"entry-dgp-36995\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σολοικίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 845 na letra σ · nº geral 36995</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. σολοικίσω, át. σολοικιῶ) 1 não respeitar as regras gramaticais da língua; falar ou escrever incorretamente: σ. τῇ φωνῇ dem. falar incorretamente a própria língua, i.e., o grego, σ. φωνῇ Σκυθικῇ her. falar mal a língua cita 2 falar ou agir contra as regras da decência; comportar-se mal; ser mal-educado. 〈σόλοικος〉</p></section></article>\n<article id=\"entry-dgp-36996\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σολοικισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 846 na letra σ · nº geral 36996</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 falta contra as regras da linguagem; solecismo 2 falta contra as regras da decência; falta de compostura, de educação. 〈σολοικίζω〉</p></section></article>\n<article id=\"entry-dgp-36997\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σολοικιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 847 na letra σ · nº geral 36997</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que comete erros gramaticais. 〈σολοικίζω〉</p></section></article>\n<article id=\"entry-dgp-36998\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σόλοικος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 848 na letra σ · nº geral 36998</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que peca contra as regras gramaticais; que fala errado 2 que peca contra as regras do decoro; mal-educado; grosseiro. 〈Σόλοι〉</p></section></article>\n<article id=\"entry-dgp-36999\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σολομών, όνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 849 na letra σ · nº geral 36999</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Salomão, filho e sucessor de Davi.</p></section></article>\n<article id=\"entry-dgp-37000\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σόλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 850 na letra σ · nº geral 37000</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 massa de ferro 2 tipo de disco 3 massa compacta.</p></section></article>\n";
